package com.keevo.identity.onboarding.adapter.out.persistence;

import jakarta.persistence.*;

import java.time.Instant;
import java.time.LocalTime;
import java.util.UUID;

/**
 * TenantPreferencesJpaEntity — JPA entity for the {@code tenant_preferences} table.
 *
 * <p>Table created by {@link com.keevo.shared.infrastructure.persistence.TenantSchemaProvisioner}
 * (DDL_TENANT_PREFERENCES constant) within each tenant's PostgreSQL schema.
 *
 * <p>UUID is generated by Hibernate — never passed from the caller.
 * Story 7.5 — added 9 report-preference columns.
 */
@Entity
@Table(name = "tenant_preferences")
public class TenantPreferencesJpaEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.UUID)
    @Column(name = "id", nullable = false, updatable = false)
    private UUID id;

    @Column(name = "sector_type", length = 30)
    private String sectorType;

    @Column(name = "eod_report_time", nullable = false)
    private LocalTime eodReportTime;

    @Column(name = "stock_alert_enabled", nullable = false)
    private boolean stockAlertEnabled;

    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    @Column(name = "updated_at", nullable = false)
    private Instant updatedAt;

    // ── Story 7.5 — Report preferences columns ────────────────────────────────

    @Column(name = "eod_report_enabled", nullable = false)
    private boolean eodReportEnabled = true;

    @Column(name = "eod_report_channel", nullable = false, length = 20)
    private String eodReportChannel = "WHATSAPP";

    @Column(name = "weekly_report_enabled", nullable = false)
    private boolean weeklyReportEnabled = true;

    @Column(name = "weekly_report_day", nullable = false)
    private int weeklyReportDay = 0;

    @Column(name = "weekly_report_time", nullable = false)
    private LocalTime weeklyReportTime = LocalTime.of(20, 0);

    @Column(name = "weekly_report_channel", nullable = false, length = 20)
    private String weeklyReportChannel = "WHATSAPP";

    @Column(name = "inventory_report_enabled", nullable = false)
    private boolean inventoryReportEnabled = true;

    @Column(name = "inventory_report_channel", nullable = false, length = 20)
    private String inventoryReportChannel = "WHATSAPP";

    @Column(name = "stock_alert_channel", nullable = false, length = 20)
    private String stockAlertChannel = "PUSH";

    // ── Story 8.1 — Trend notification preference ─────────────────────────────

    @Column(name = "trend_notification_enabled", nullable = false)
    private boolean trendNotificationEnabled = true;

    // ── JPA requires no-arg constructor ───────────────────────────────────────
    protected TenantPreferencesJpaEntity() {}

    /** Factory constructor — id is intentionally omitted; Hibernate generates it. */
    public TenantPreferencesJpaEntity(String sectorType, LocalTime eodReportTime,
                                       boolean stockAlertEnabled, Instant createdAt,
                                       Instant updatedAt) {
        this.sectorType = sectorType;
        this.eodReportTime = eodReportTime;
        this.stockAlertEnabled = stockAlertEnabled;
        this.createdAt = createdAt;
        this.updatedAt = updatedAt;
    }

    // ── Accessors ────────────────────────────────────────────────────────────

    public UUID getId() { return id; }
    public String getSectorType() { return sectorType; }
    public LocalTime getEodReportTime() { return eodReportTime; }
    public boolean isStockAlertEnabled() { return stockAlertEnabled; }
    public Instant getCreatedAt() { return createdAt; }
    public Instant getUpdatedAt() { return updatedAt; }

    // ── Story 7.5 setters / getters ───────────────────────────────────────────

    public boolean isEodReportEnabled() { return eodReportEnabled; }
    public void setEodReportEnabled(boolean v) { this.eodReportEnabled = v; }

    public String getEodReportChannel() { return eodReportChannel; }
    public void setEodReportChannel(String v) { this.eodReportChannel = v; }

    public boolean isWeeklyReportEnabled() { return weeklyReportEnabled; }
    public void setWeeklyReportEnabled(boolean v) { this.weeklyReportEnabled = v; }

    public int getWeeklyReportDay() { return weeklyReportDay; }
    public void setWeeklyReportDay(int v) { this.weeklyReportDay = v; }

    public LocalTime getWeeklyReportTime() { return weeklyReportTime; }
    public void setWeeklyReportTime(LocalTime v) { this.weeklyReportTime = v; }

    public String getWeeklyReportChannel() { return weeklyReportChannel; }
    public void setWeeklyReportChannel(String v) { this.weeklyReportChannel = v; }

    public boolean isInventoryReportEnabled() { return inventoryReportEnabled; }
    public void setInventoryReportEnabled(boolean v) { this.inventoryReportEnabled = v; }

    public String getInventoryReportChannel() { return inventoryReportChannel; }
    public void setInventoryReportChannel(String v) { this.inventoryReportChannel = v; }

    public String getStockAlertChannel() { return stockAlertChannel; }
    public void setStockAlertChannel(String v) { this.stockAlertChannel = v; }

    public boolean isTrendNotificationEnabled() { return trendNotificationEnabled; }
    public void setTrendNotificationEnabled(boolean v) { this.trendNotificationEnabled = v; }

    public void setUpdatedAt(Instant v) { this.updatedAt = v; }
    public void setStockAlertEnabled(boolean v) { this.stockAlertEnabled = v; }
    public void setEodReportTime(LocalTime v) { this.eodReportTime = v; }
    public void setSectorType(String v) { this.sectorType = v; }
}

